scripts.script:
// 寰斗指魂：格挡成功后为攻击者打下“狩魂”标记（1 回合，时长见 AE 模板）。
// 狩魂的“总能选中”超出系统目标机制，由玩家/GM 按描述手动把握。
if (!Macros.checkStance(actor, args)) return;
if (!args.attacker) return;
const hdEff = thisItem.effects.getName('狩魂');
if (!hdEff) return;
const hdData = hdEff.toObject();
hdData.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(args.attacker, hdData);
ui.notifications.info('邪秽显迹：' + args.attacker.name + ' 被打下“狩魂”标记（1 回合）。');

// 游心慑灵：命中 [恶][邪] 角色时为其打下“狩魂”标记（1 回合，时长见 AE 模板）。
if (!args.isHit || !args.target) return;
const yxS = args.target.system?.social;
if (!yxS) return;
if (!(yxS.exing >= 100 && yxS.xiayi <= 50)) return;
const yxEff = thisItem.effects.getName('狩魂');
if (!yxEff) return;
const yxData = yxEff.toObject();
yxData.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(args.target, yxData);
ui.notifications.info('邪秽显迹：' + args.target.name + ' 被打下“狩魂”标记（1 回合）。');

// 护灵障：施展后在原地（不跟随）生成 3 米护灵障，持续 3 回合（单实例，再次施展自动替换）；
// 区域内敌人各自回合初受 40+20×(升级-1) 点精神伤害（必中不暴击）。
// “区域外角色无法选中区域内角色”超出系统目标机制，由玩家/GM 按描述手动把握。
const hlLvl = Math.max(1, move.computedLevel || 1);
await game.xjzl.aura.create(actor, {
    label: 'wuxue-hulingzhang-' + actor.id,
    displayName: '护灵障',
    follow: false,
    radius: 3,
    faction: 'enemy',
    includeSelf: false,
    enterEnabled: false,
    roundEnabled: true,
    roundTiming: 'tokenTurnStart',
    roundAction: { kind: 'damage', amount: String(40 + 20 * (hlLvl - 1)), type: 'mental' },
    durationRounds: 3,
    lifecycle: 'combat',
    combatId: game.combat?.id ?? null,
    cleanupOnExit: true
});

// 拘魂点脉：命中无架招且气感低于你的敌人时，施加“禁足”（1 回合）。
if (!args.isHit || !args.target) return;
if (args.target.system?.martial?.stanceActive) return;
const jgMy = actor.system?.stats?.qigan?.total || 0;
const jgTgt = args.target.system?.stats?.qigan?.total || 0;
if (jgTgt >= jgMy) return;
const jgEff = game.xjzl.api.effects.getStatus('root');
if (!jgEff) return;
const jgData = foundry.utils.deepClone(jgEff);
jgData.duration = { value: 1, units: 'rounds', expiry: 'turnStart' };
await game.xjzl.api.effects.addEffect(args.target, jgData);
ui.notifications.info('拘魂点脉：' + args.target.name + ' 气感不及你，被禁足（1 回合）。');

// 净魂扫邪：击破架招时移除目标身上任意一个状态——移除哪个状态需玩家选择，保持手动；
// 破架为全桌可见事件，用聊天卡片提醒而非本地通知。
if (!args.isBroken || !args.target) return;
await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor: actor }),
    content: '<div class="xjzl-chat-card" style="padding: 5px 8px;"><b>净魂扫邪</b>：击破了 ' + args.target.name + ' 的架招！请手动移除其身上任意一个状态。</div>'
});

// 唤魂归阴：对每个选中目标请求 [定力] 检定（难度 15+升级-1），失败自动陷入倒地；
// 失败者朝施术者方向移动 1+升级-1 米，位移超出自动化框架，请手动结算。
if (!args.target) return;
const hyLvl = Math.max(1, move.computedLevel || 1);
const hyDc = 15 + (hyLvl - 1);
const hyDist = 1 + (hyLvl - 1);
await Macros.requestSave({
    target: args.target,
    attacker: actor,
    type: 'dingli',
    dc: hyDc,
    label: '唤魂归阴',
    item: thisItem,
    move: args.move,
    onFail: 'prone',
    failureText: '魂魄受牵，你俯身趴地陷入倒地，并被牵引朝施术者方向移动 ' + hyDist + ' 米（请手动移动）。'
});

// 破魂斩浊：命中 [恶][邪] 角色时使其陷入“碎魂”（持续到战斗脱离，战斗结束后手动移除）。
if (!args.isHit || !args.target) return;
const phS = args.target.system?.social;
if (!phS) return;
if (!(phS.exing >= 100 && phS.xiayi <= 50)) return;
const phEff = thisItem.effects.getName('碎魂');
if (!phEff) return;
const phData = phEff.toObject();
phData.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(args.target, phData);
ui.notifications.info('阴阳归位：' + args.target.name + ' 陷入“碎魂”，持续到战斗脱离。');

// 碎魂：每回合初流失等同于自身神采数值的气血（liushi 真实伤害）和内力（资源直接流失）。
const shSc = Math.max(0, S.stats?.shencai?.total || 0);
if (shSc <= 0) return;
await actor.applyDamage({ amount: shSc, type: 'liushi', source: 'dot' });
await actor.applyHealing({ amount: -shSc, type: 'mp', source: 'dot', showScrolling: true });

// 觉灵视：进入“灵视”状态（3 回合，时长见 AE 模板）。
// 选中“不可选中”目标与对其命中+5 超出系统目标机制，由玩家/GM 按描述手动把握。
const jsEff = thisItem.effects.getName('灵视');
if (!jsEff) return;
const jsData = jsEff.toObject();
jsData.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, jsData);
ui.notifications.info('灵视已开启（3 回合）。');

// 铸灵兵：为自身挂上“灵兵”状态（同 slug 重复施展即刷新加成与时长）。
// 加成随修炼层数变化：一层武器伤害+5；二层追加武器格挡+5；三层武器伤害+10、武器格挡+10。
// 附魂仪式、飞回手中与先攻替换为手动流程；通神共鸣的暴击怒气由“灵兵”状态脚本结算。
const lbLvl = Math.max(1, move.computedLevel || 1);
const lbDmg = lbLvl >= 3 ? 10 : 5;
const lbBlock = lbLvl >= 3 ? 10 : (lbLvl >= 2 ? 5 : 0);
const lbEff = thisItem.effects.getName('灵兵');
if (!lbEff) return;
const lbData = lbEff.toObject();
lbData.origin = thisItem.uuid;
lbData.system.changes = [{ key: 'system.combat.damages.weapon.mod', type: 'add', value: String(lbDmg) }];
if (lbBlock > 0) lbData.system.changes.push({ key: 'system.combat.block', type: 'add', value: String(lbBlock) });
await game.xjzl.api.effects.addEffect(actor, lbData);
ui.notifications.info('灵兵加成已生效（第' + lbLvl + '层）：武器伤害+' + lbDmg + (lbBlock > 0 ? '，武器格挡+' + lbBlock : '') + '。');

// 通神共鸣（御魂层）：使用灵兵出招命中且暴击时，额外获得 1 点怒气，并发卡片告知全桌。
// 需《铸灵兵》修炼至第三层；排除治疗/Buff 与普攻（趁虚而入仍算出招）；
// 持有本状态即代表正在使用灵兵，不再检测具体武器；手动结算未命中不回怒。
if (!args.isHit || !args.isCrit) return;
if (['heal', 'buff'].includes(args.actionType)) return;
if (args.move?.type === 'basic' && args.move.id !== 'opportunity-attack') return;
const gyBook = (thisEffect?.parent?.type === 'wuxue') ? thisEffect.parent : actor.items.find(i => i.name === '铸灵兵');
if ((gyBook?.system?.moves?.[0]?.computedLevel || 0) < 3) return;
await actor.changeResources({
    'system.resources.rage.value': { delta: 1 }
}, { cause: 'script', sourceActor: actor, item: args.item, move: args.move, source: 'lingshi_gongming' });
await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor: actor }),
    content: '<div class="xjzl-chat-card" style="padding: 5px 8px;"><b>通神共鸣</b>：' + actor.name + ' 的灵兵出招暴击，人兵合一，额外获得 1 点怒气。</div>'
});
